# Generated by build.py from recipe.yml for recipe http-find-failed-logins-in-the-log. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.csv'), "id,total`n1,40`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--user', 'app:s3cret', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { grep -E "Login (accepted|refused)|forbade" surl.log } finally { Stop-Process $server0 }
